#!/usr/bin/env python3
import urllib.request,json,re,os,time
from datetime import datetime,timezone
C='2026-09-24_cycle-10';O='/opt/data/results/vac-2026-09-24_cycle-10-source-remotive.com';W=O+'/.worker-state'
for d in(W,W+'/raw',W+'/completed'):os.makedirs(d,exist_ok=True)
now=datetime.now(timezone.utc).isoformat();u='https://remotive.com/api/remote-jobs?search=QA';req=urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0'});data=urllib.request.urlopen(req,timeout=60).read();open(W+'/raw/api.json','wb').write(data);d=json.loads(data);records=[x for x in d.get('jobs',[]) if re.search(r'\bQA\b|Quality Assurance|Software Test',x.get('title',''),re.I) and re.search(r'Germany|Deutschland|Berlin|Leipzig|Dresden|Europe',str(x),re.I)]
rows=[]
for i,x in enumerate(records,1):
 t=str(x.get('description',''));loc=x.get('candidate_required_location','');ok=bool(re.search(r'Germany|Deutschland',loc) or re.search(r'Germany|Deutschland',t,re.I));p=W+'/raw/card_'+str(i)+'.json';open(p,'w').write(json.dumps(x,ensure_ascii=False,indent=2));
 if ok:rows.append({'title':x.get('title'),'company':x.get('company_name'),'url':x.get('url'),'location':'Germany-wide Remote','role':'Other QA Roles' if not re.search(r'automat|engineer',x.get('title',''),re.I) else 'Software Test / Automation','posted':x.get('publication_date'),'work_mode':'Remote','evidence':p});open(W+'/completed/'+str(i)+'.json','w').write(json.dumps(rows[-1],ensure_ascii=False,indent=2))
lines=['# Remotive — '+C,'',f'Accepted rows: {len(rows)}.','','| # | Position | Company | Location axis | Role axis | Posted | Work mode |','|---:|---|---|---|---|---|---|']+[f"| {i} | [{r['title']}]({r['url']}) | {r['company']} | {r['location']} | {r['role']} | {r['posted']} | {r['work_mode']} |" for i,r in enumerate(rows,1)];open(O+'/result.md','w').write('\n'.join(lines)+'\n');open(W+'/result.md','w').write(f'accepted={len(rows)}\n');open(O+'/source_coverage.md','w').write(f'# Source coverage — remotive.com\nCycle {C}; public API search=QA; Germany/DE remote and all QA role categories checked semantically; records {len(d.get("jobs",[]))}, candidates {len(records)}, accepted {len(rows)}.\n');open(O+'/provenance.json','w').write(json.dumps({'cycle_id':C,'source_id':'remotive.com','api':u,'records':len(d.get('jobs',[])),'candidates':len(records),'accepted':len(rows),'checked_at':now},indent=2));
for n,o in [('plan',{'cycle_id':C,'source_id':'remotive.com','method':'public API'}),('checkpoint',{'cycle_id':C,'status':'complete','accepted':len(rows),'next_cursor':1}),('failures',{'cycle_id':C,'failures':[]}),('manifest',{'cycle_id':C,'source_id':'remotive.com','status':'complete','owner':'worker-1','finished_at':now,'metrics':{'accepted':len(rows)}})] :open(W+'/'+n+'.json','w').write(json.dumps(o,indent=2))
print(len(rows))
